#include <bits/stdc++.h>using namespace std;#define int long longint n,T,cnt; void O_o(){    cnt = 0;    vector<int> ans;    cin >> n;    vector<pair<int,int>> a(n + 1);    vector<bool> ok(n + 1,1);    for(int i=1;i<=n;i++){        cin >> a[i].first >> a[i].second;    }    for(int i=1;i<=n;i++){        for(int j=1;j<=n;j++){            if(j == i || !ok[j])continue;            if(a[i].first <= a[j].first && a[j].second <= a[i].second){                ok[j] = 0;            }        }    }    for(int i=1;i<=n;i++){        if(ok[i]){            cnt++;            ans.push_back(i);        }    }    cout << cnt << '\n';    for(auto &x : ans){        cout << x << ' ';    }    cout << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> T;    while(T--)O_o();    return 0;}